create table public.web_vital_samples(id bigint generated always as identity primary key,user_id uuid references auth.users(id) on delete set null,metric_id text not null,metric_name text not null check(metric_name in('CLS','FCP','FID','INP','LCP','TTFB')),metric_value numeric not null,rating text not null check(rating in('good','needs-improvement','poor')),path text not null,navigation_type text,created_at timestamptz not null default now());
create table public.locale_content_packs(id uuid primary key default gen_random_uuid(),locale text not null,region_code text not null,namespace text not null,version text not null,messages jsonb not null check(jsonb_typeof(messages)='object'),status text not null default 'draft' check(status in('draft','review','published','retired')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now(),unique(locale,region_code,namespace,version));
create table public.integration_clients(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id),name text not null,client_type text not null check(client_type in('mcp','webhook','api_import')),scopes text[] not null default '{}',secret_hash text,status text not null default 'active' check(status in('active','suspended','revoked')),rate_limit_per_minute integer not null default 60,last_used_at timestamptz,created_at timestamptz not null default now());
create table public.webhook_deliveries(id bigint generated always as identity primary key,integration_client_id uuid not null references public.integration_clients(id) on delete cascade,event_type text not null,payload jsonb not null,endpoint_url text not null,status text not null default 'pending' check(status in('pending','processing','delivered','failed','dead_letter')),attempt_count integer not null default 0,next_attempt_at timestamptz not null default now(),response_code integer,last_error text,created_at timestamptz not null default now(),delivered_at timestamptz);
alter table public.web_vital_samples enable row level security;alter table public.locale_content_packs enable row level security;alter table public.integration_clients enable row level security;alter table public.webhook_deliveries enable row level security;
create policy "bounded vitals insert" on public.web_vital_samples for insert with check(user_id is null or user_id=auth.uid());create policy "staff read vitals" on public.web_vital_samples for select using(public.is_platform_staff());create policy "published locale packs readable" on public.locale_content_packs for select using(status='published');create policy "staff manage locale packs" on public.locale_content_packs for all using(public.is_platform_staff()) with check(public.is_platform_staff());create policy "staff manage integrations" on public.integration_clients for all using(public.is_platform_staff()) with check(public.is_platform_staff());create policy "staff read webhook delivery" on public.webhook_deliveries for select using(public.is_platform_staff());
create index vitals_metric_time_idx on public.web_vital_samples(metric_name,created_at desc);create index locale_pack_lookup_idx on public.locale_content_packs(locale,region_code,namespace,status);create index webhook_ready_idx on public.webhook_deliveries(status,next_attempt_at) where status in('pending','failed');
